```ts
function withTimeout<T>(ms: number) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  return { signal: controller.signal, dispose: () => clearTimeout(timer) };
}

// CallTool内
const timeoutMs = tool.timeoutMs ?? Number(process.env.MCP_TOOL_TIMEOUT_MS ?? 60000);
const { signal, dispose } = withTimeout(timeoutMs);
try {
  const result = await tool.handler(parsedArgs, { signal, requestId });
  return ok(result);
} catch (e) {
  if (signal.aborted) throw new AppError('TIMEOUT', `Tool timed out: ${name}`, true);
  throw e;
} finally {
  dispose();
}
```

