import pLimit from 'p-limit';

const limiters = new Map<string, ReturnType<typeof pLimit>>();
function getLimiter(toolName: string, n: number) {
  const key = `${toolName}:${n}`;
  if (!limiters.has(key)) limiters.set(key, pLimit(n));
  return limiters.get(key)!;
}

// CallTool内
const limiter = getLimiter(name, tool.maxConcurrency ?? 4);
const result = await limiter(() => tool.handler(parsedArgs, { signal, requestId }));
